def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_def = 0
    for _, b in history:
        if b == 'D':
            opp_def += 1
    opp_rate = opp_def / n

    if opp_rate > 0.5:
        return 'D'

    last = history[-1][1]
    if last == 'D':
        if n >= 2 and history[-2][1] == 'D':
            return 'D'
        if opp_rate < 0.3:
            return 'C'
        return 'D'

    if opp_def == 0:
        if n >= 10 and n % 10 == 0 and n <= 80:
            return 'D'
        if n >= 90:
            return 'D'

    return 'C'
